                            seen.add((yy,xx)); q.append((yy,xx))
                out.append((col,cs))
    return out

def center(cs):
    return (sum(p[0] for p in cs)/len(cs), sum(p[1] for p in cs)/len(cs))

def edist(a,b):
    return math.hypot(a[0]-b[0],a[1]-b[1])

def transform(grid):
    g=grid
    bg=max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    ci=comps4(g,bg); cnt=defaultdict(int)
